请对以下 case 进行三维加权评分。

=== case_id ===
Case-21-stocks-007

=== 用户原始指令 (query.txt) ===
搞个基金涨跌数字会变的，能看今天天气，跌破线要红色警告

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个基金涨跌数字会变的，能看今天天气，跌破线要红色警告",
  "size": "2x4",
  "eventCandidates": [],
  "dataModelSchema": {
    "data": {
      "fund": {
        "name": {
          "type": "string",
          "description": "基金简称或代码展示文本。",
          "sampleValue": "新能源ETF"
        },
        "netValueText": {
          "type": "string",
          "description": "基金当前净值或估值展示文本。",
          "sampleValue": "0.8732"
        },
        "changeValueText": {
          "type": "string",
          "description": "基金当日涨跌额展示文本，包含正负号。",
          "sampleValue": "-0.018"
        },
        "changePercentText": {
          "type": "string",
          "description": "基金当日涨跌幅展示文本，包含百分号。",
          "sampleValue": "-2.05%"
        },
        "thresholdText": {
          "type": "string",
          "description": "用户关注的跌破阈值线展示文本。",
          "sampleValue": "0.8800"
        },
        "alertText": {
          "type": "string",
          "description": "跌破阈值后的告警状态短文本。",
          "sampleValue": "跌破线警告"
        },
        "statusText": {
          "type": "string",
          "description": "基金相对阈值线的当前状态短文本。",
          "sampleValue": "已跌破"
        },
        "lineGapText": {
          "type": "string",
          "description": "基金当前值相对阈值线的差距展示文本。",
          "sampleValue": "-0.8%"
        },
        "alertColor": {
          "type": "string",
          "description": "告警状态使用的颜色值，跌破阈值时为红色告警色。",
          "sampleValue": "#ffed6f21"
        }
      },
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "今日当前温度展示文本。",
            "sampleValue": "24℃"
          },
          "condition": {
            "type": "string",
            "description": "今日当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

